App.my.KEY = 'expenses';
App.my.CATS = ['🏠 ఇల్లు', '⛽ పెట్రోల్', '🍛 భోజనం', '🛒 సరుకులు', '💊 మందులు', '🚌 ప్రయాణం', '📦 ఇతర'];
App.my.list = () => App.items(App.my.KEY).slice().sort((a, b) => (b.date || '').localeCompare(a.date || '') || b.at - a.at);
App.my.inMonth = (key) => App.items(App.my.KEY).filter((e) => App.monthKey(e.date) === key);
App.my.sum = (l) => l.reduce((s, e) => s + (Number(e.amount) || 0), 0);
App.my.guess = (w) => {
  const t = String(w || '').toLowerCase();
  const map = [[/పెట్రోల్|డీజిల్|petrol|diesel|fuel/, 1], [/భోజన|టిఫిన్|హోటల్|టీ|కాఫీ|food|hotel|tea/, 2],
    [/సరుకు|కూరగాయ|పాలు|బియ్యం|grocery|vegetable|milk/, 3], [/మందు|డాక్టర్|హాస్పిటల్|medicine|doctor/, 4],
    [/బస్|ఆటో|ట్రైన్|టికెట్|bus|auto|train|ticket/, 5], [/అద్దె|కరెంట్|రెంట్|rent|current|bill/, 0]];
  for (const [re, i] of map) if (re.test(t)) return App.my.CATS[i];
  return App.my.CATS[6];
};
App.my.widget = async () => {
  const month = App.my.sum(App.my.inMonth(App.monthKey(new Date())));
  const today = App.my.sum(App.items(App.my.KEY).filter((e) => e.date === App.today()));
  try { await App.widget('💰 ఖర్చులు', ['ఈ నెల: ' + App.rs(month), 'ఈ రోజు: ' + App.rs(today)]); } catch (e) { /* the widget only helps */ }
};
App.onStart(() => { App.my.widget(); });
App.onJarvis('add', (d) => {
  const amount = Number(d.amount);
  if (!(amount > 0)) return 'ఎంతో చెప్పలేదు, ఏమీ రాయలేదు';
  const what = String(d.what || '').trim().slice(0, 80);
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(d.date || '')) ? d.date : App.today();
  App.add(App.my.KEY, { amount, what, cat: App.my.guess(what), date });
  App.my.widget();
  return App.rs(amount) + (what ? ' ' + what : '') + ' ఖర్చు రాశాను';
});

App.onShow('home', () => {
  App.text('#home-month', App.rs(App.my.sum(App.my.inMonth(App.monthKey(new Date())))));
  App.text('#home-today', App.rs(App.my.sum(App.items(App.my.KEY).filter((e) => e.date === App.today()))));
  const l = App.my.list().slice(0, 200);
  App.set('#home-list', l.length ? '<div class="list">' + l.map((e) => `
    <div class="item" data-id="${App.esc(e.id)}">
      <div class="ic">${App.esc(String(e.cat || '📦').split(' ')[0])}</div>
      <div class="w"><div class="t">${App.esc(e.what || String(e.cat || 'ఖర్చు').split(' ').slice(1).join(' ') || 'ఖర్చు')}</div><div class="s">${App.date(e.date)}</div></div>
      <div class="r">${App.rs(e.amount)}</div>
    </div>`).join('') + '</div>'
    : '<div class="empty"><div class="e">🧾</div>ఇంకా ఖర్చులు లేవు. + నొక్కి రాయండి.<div class="faint">Jarvis తో: "ఖర్చుల లెక్కలో 200 పెట్రోల్ రాయి"</div></div>');
});
App.click('#home-add', () => App.go('add'));
App.click('#home-list .item', (ev, el) => App.go('add', App.find(App.my.KEY, el.dataset.id)));

App.onShow('add', (e) => {
  App.my.editing = e && e.id ? e.id : null;
  App.title(App.my.editing ? 'ఖర్చు మార్చండి' : 'కొత్త ఖర్చు');
  App.set('#add-cat', App.my.CATS.map((c) => `<option>${App.esc(c)}</option>`).join(''));
  App.val('#add-amt', e && e.amount != null ? e.amount : '');
  App.val('#add-what', e && e.what ? e.what : '');
  App.val('#add-cat', e && e.cat ? e.cat : App.my.CATS[6]);
  App.val('#add-date', e && e.date ? e.date : App.today());
  App.show('#add-del', !!App.my.editing);
});
App.on('#add-what', 'change', () => {
  const g = App.my.guess(App.val('#add-what'));
  if (!App.my.editing && g !== App.my.CATS[6]) App.val('#add-cat', g);
});
App.click('#add-save', () => {
  const amount = Number(App.val('#add-amt'));
  if (!(amount > 0)) { App.toast('ఎంత అయిందో రాయండి'); return; }
  const rec = { amount, what: App.val('#add-what').slice(0, 80), cat: App.val('#add-cat') || App.my.CATS[6], date: App.val('#add-date') || App.today() };
  if (App.my.editing) App.update(App.my.KEY, App.my.editing, rec); else App.add(App.my.KEY, rec);
  App.my.widget();
  App.beep('ok');
  App.toast('దాచాను');
  App.back();
});
App.click('#add-del', async () => {
  if (!App.my.editing) return;
  if (await App.ask('ఈ ఖర్చు తీసేయాలా?', 'తీసేయి', 'వద్దు')) { App.del(App.my.KEY, App.my.editing); App.my.widget(); App.toast('తీసేశాను'); App.back(); }
});

App.my.months = () => { const out = []; for (let i = 0; i < 6; i++) { const d = new Date(); d.setDate(1); d.setMonth(d.getMonth() - i); out.push(App.monthKey(d)); } return out; };
App.my.byCat = (l) => { const by = {}; for (const e of l) { const c = e.cat || App.my.CATS[6]; by[c] = (by[c] || 0) + (Number(e.amount) || 0); } return by; };
App.my.key = () => App.val('#sum-month') || App.monthKey(new Date());
App.my.drawSum = () => {
  const key = App.my.key(), l = App.my.inMonth(key), by = App.my.byCat(l);
  App.text('#sum-total', App.rs(App.my.sum(l)));
  App.text('#sum-count', l.length + ' ఖర్చులు');
  if (l.length) App.chart('#sum-pie', { type: 'pie', labels: Object.keys(by), values: Object.values(by), money: true });
  else App.set('#sum-pie', '<div class="muted">ఈ నెల ఖర్చులు లేవు</div>');
  const ms = App.my.months().reverse();
  App.chart('#sum-bars', { type: 'bar', labels: ms.map((m) => App.month(m + '-01').split(' ')[0]), values: ms.map((m) => App.my.sum(App.my.inMonth(m))), money: true });
};
App.onShow('summary', () => {
  const keep = App.val('#sum-month'), ms = App.my.months();
  App.set('#sum-month', ms.map((k) => `<option value="${k}">${App.esc(App.month(k + '-01'))}</option>`).join(''));
  App.val('#sum-month', ms.includes(keep) ? keep : ms[0]);
  App.my.drawSum();
});
App.on('#sum-month', 'change', () => App.my.drawSum());
App.click('#sum-share', async () => {
  const key = App.my.key(), l = App.my.inMonth(key), by = App.my.byCat(l);
  const lines = ['💰 ' + App.month(key + '-01') + ' ఖర్చులు: ' + App.rs(App.my.sum(l))].concat(Object.keys(by).map((c) => c + ': ' + App.rs(by[c])));
  try { await App.share(lines.join('\n')); } catch (e) { App.toast('షేర్ కాలేదు'); }
});
App.click('#sum-pdf', async () => {
  const key = App.my.key(), l = App.my.inMonth(key).sort((a, b) => (a.date || '').localeCompare(b.date || ''));
  const rows = l.map((e) => `<tr><td>${App.date(e.date, 'short')}</td><td>${App.esc(e.what || '')}</td><td>${App.esc(e.cat || '')}</td><td class="n">${App.rs(e.amount)}</td></tr>`).join('');
  const html = `<h2>${App.esc(App.month(key + '-01'))} ఖర్చులు</h2><p>మొత్తం: <b>${App.rs(App.my.sum(l))}</b> (${l.length} ఖర్చులు)</p>`
    + `<table><tr><th>తేదీ</th><th>దేనికి</th><th>రకం</th><th>ఎంత</th></tr>${rows}</table>`;
  try { await App.pdf('ఖర్చులు ' + key, html); } catch (e) { App.toast('PDF కాలేదు'); }
});
